:focus{
    border:2px solid var(--brand-color)!important;
    box-shadow:none!important
}
.sp_choice_type_11:focus,.sp_choice_type_12:focus,.sp_choice_type_13:focus,.sp_choice_type_SE:focus{
    outline:2px solid var(--brand-color)!important
}
.sp_choice_type_11:focus,.sp_choice_type_13:focus,.sp_choice_type_SE:focus{
    outline-offset:2px!important
}
:root{
    --brand-color:#0d7680
}
p{
    padding-bottom:10px
}
p+p{
    margin-top:1rem!important
}
button{
    cursor:pointer;
    border:none
}
.global-font :where(p,button,span,input){
    font-family:MetricWeb!important;
    font-size:16px!important
}
.message{
    grid-template-rows:1fr auto !important;
    max-width:650px!important;
    height:100vh!important;
    display:grid!important
}
@media only screen{
    @media (min-width:600px){
        .message{
            height:min(700px,70vh)!important
        }
        @media (max-height:720px){
            .message{
                height:90svh!important
            }
        }
    }
}
.cookie_heading{
    padding:0 25px 20px 0!important;
    font-family:MetricWeb!important;
    font-size:24px!important;
    font-weight:700!important
}
@media only screen and (min-width:600px){
    .cookie_heading{
        padding:0 25px 16px 0!important
    }
}
.cookie_heading:after{
    content:"";
    background:var(--brand-color);
    width:5rem;
    height:.375rem;
    margin-top:.5rem;
    margin-left:.1rem;
    display:block
}
.heading_main_text_wrapper{
    align-content:start!important;
    margin:2.5em 1.5em 0!important;
    display:grid!important;
    overflow-x:hidden!important;
    overflow-y:auto!important
}
.heading_main_text_wrapper::-webkit-scrollbar{
    display:none!important
}
@media only screen and (min-width:600px){
    .heading_main_text_wrapper{
        width:550px!important;
        margin:40px 48px 0!important
    }
}
.main_body{
    display:grid!important
}
@media only screen and (min-width:600px){
    .main_body{
        border-bottom:1px solid #bbb!important;
        gap:1rem!important;
        padding-bottom:1rem!important;
        display:flex!important
    }
}
.dropdown_wrapper{
    padding-top:14px!important
}
@media only screen and (min-width:600px){
    .dropdown_wrapper{
        -ms-overflow-style:none;
        scrollbar-width:none;
        grid-template-rows:auto 1fr auto;
        height:190px!important;
        padding-top:0!important;
        overflow-x:hidden!important;
        overflow-y:auto!important
    }
    .dropdown_wrapper::-webkit-scrollbar{
        display:none!important
    }
}
.message-stacks{
    margin-top:1.5rem!important
}
@media only screen and (min-width:600px){
    .message-stacks{
        margin-top:1rem!important
    }
}
.accordion{
    display:flex;
    background:#fff!important;
    padding-bottom:24px!important;
    padding-left:2rem!important
}
.accordion .chevron{
    padding-top:5px;
    float:left!important;
    left:0!important
}
.footer{
    justify-content:initial!important;
    z-index:1!important;
    padding:24px 24px 32px!important;
    display:grid!important;
    box-shadow:0 -1px 15px #0008!important
}
@media only screen and (min-width:600px){
    .footer{
        box-shadow:none!important;
        padding:32px 48px 40px!important
    }
}
.footer__controls{
    justify-content:initial!important;
    gap:1rem!important;
    display:grid!important
}
